<?php defined('_JEXEC') or die;use Joomla\CMS\HTML\HTMLHelper;use Joomla\CMS\Router\Route; ?><div class="container-fluid"><h1>Vehicle List</h1><div class="row g-3 mb-4"><?php foreach($this->stats as $label=>$value): ?><div class="col-6 col-lg-3"><div class="card"><div class="card-body"><div class="text-muted"><?php echo ucfirst($label); ?></div><strong class="fs-3"><?php echo $value; ?></strong></div></div></div><?php endforeach; ?></div><div class="card mb-4"><div class="card-body"><h2 class="h4">Add vehicle</h2><form method="post" enctype="multipart/form-data" action="<?php echo Route::_('index.php?option=com_kaarbooking&task=vehicles.save'); ?>" class="row g-3"><div class="col-md-2"><input class="form-control" name="registration_number" required placeholder="Registration"></div><div class="col-md-2"><select class="form-select" name="vehicle_type_id" required><option value="">Vehicle type</option><?php foreach($this->types as $r): ?><option value="<?php echo (int)$r['id']; ?>"><?php echo htmlspecialchars($r['title'],ENT_QUOTES,'UTF-8'); ?></option><?php endforeach; ?></select></div><div class="col-md-2"><select class="form-select" name="company_id"><option value="">Operator owned</option><?php foreach($this->companies as $r): ?><option value="<?php echo (int)$r['id']; ?>"><?php echo htmlspecialchars($r['name'],ENT_QUOTES,'UTF-8'); ?></option><?php endforeach; ?></select></div><div class="col-md-2"><input class="form-control" name="make" placeholder="Make"></div><div class="col-md-2"><input class="form-control" name="model" placeholder="Model"></div><div class="col-md-1"><input class="form-control" type="number" min="1950" max="2100" name="model_year" placeholder="Year"></div><div class="col-md-2"><select class="form-select" name="condition_status"><option value="new">New</option><option value="excellent">Excellent</option><option value="good" selected>Good</option><option value="fair">Fair</option><option value="maintenance_required">Maintenance required</option></select></div><div class="col-md-2"><input class="form-control" type="number" min="0" step="0.1" name="odometer_km" placeholder="Odometer km"></div><div class="col-md-3"><input class="form-control" type="file" name="vehicle_image" accept="image/jpeg,image/png,image/webp" required aria-label="Vehicle image"></div><div class="col-md-2"><button class="btn btn-primary">Add vehicle</button></div><?php echo HTMLHelper::_('form.token'); ?></form></div></div><form method="get" class="row g-2 mb-3"><input type="hidden" name="option" value="com_kaarbooking"><input type="hidden" name="view" value="vehicles"><div class="col-md-3"><input class="form-control" name="filter_search" value="<?php echo htmlspecialchars($this->filters['search'],ENT_QUOTES,'UTF-8'); ?>" placeholder="Registration, make or model"></div><div class="col-md-2"><select class="form-select" name="filter_type"><option value="">All vehicle types</option><?php foreach($this->types as $r): ?><option value="<?php echo $r['id']; ?>" <?php echo $this->filters['type']==$r['id']?'selected':''; ?>><?php echo htmlspecialchars($r['title'],ENT_QUOTES,'UTF-8'); ?></option><?php endforeach; ?></select></div><div class="col-md-2"><select class="form-select" name="filter_company"><option value="">All owners</option><?php foreach($this->companies as $r): ?><option value="<?php echo $r['id']; ?>" <?php echo $this->filters['company']==$r['id']?'selected':''; ?>><?php echo htmlspecialchars($r['name'],ENT_QUOTES,'UTF-8'); ?></option><?php endforeach; ?></select></div><div class="col-md-2"><select class="form-select" name="filter_compliance"><option value="">All compliance</option><option>pending</option><option>verified</option><option>non_compliant</option><option>blocked</option></select></div><div class="col-md-2"><button class="btn btn-secondary">Filter</button> <a class="btn btn-link" href="<?php echo Route::_('index.php?option=com_kaarbooking&view=vehicles'); ?>">Clear</a></div></form><div class="table-responsive"><table class="table table-striped"><thead><tr><th>Image</th><th>Registration</th><th>Owner</th><th>Type</th><th>Make/model</th><th>Year</th><th>Condition</th><th>Operational</th><th>Compliance</th></tr></thead><tbody><?php foreach($this->items as $i): ?><tr><td><?php if(!empty($i['image_path'])): ?><img src="<?php echo htmlspecialchars(\Joomla\CMS\Uri\Uri::root().$i['image_path'],ENT_QUOTES,'UTF-8'); ?>" alt="" width="64" height="48" style="object-fit:cover" loading="lazy"><?php endif; ?></td><td><?php echo htmlspecialchars($i['registration_number'],ENT_QUOTES,'UTF-8'); ?></td><td><?php echo htmlspecialchars($i['company_name']??'Operator',ENT_QUOTES,'UTF-8'); ?></td><td><?php echo htmlspecialchars($i['type_title']??'',ENT_QUOTES,'UTF-8'); ?></td><td><?php echo htmlspecialchars(trim($i['make'].' '.$i['model']),ENT_QUOTES,'UTF-8'); ?></td><td><?php echo (int)$i['model_year']; ?></td><td><?php echo htmlspecialchars($i['condition_status'],ENT_QUOTES,'UTF-8'); ?></td><td><?php echo htmlspecialchars($i['operational_status'],ENT_QUOTES,'UTF-8'); ?></td><td><?php echo htmlspecialchars($i['compliance_status'],ENT_QUOTES,'UTF-8'); ?></td></tr><?php endforeach; ?><?php if(!$this->items): ?><tr><td colspan="9">No vehicles match the filters.</td></tr><?php endif; ?></tbody></table></div></div>




